const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountLibrary(cards,tags,registry,onChange){
 const byId=new Map(cards.map(c=>[c.id,c]));let mode='sets',limit=24,focus=null,selection=[],lastRemoved=null;
 const chips=list=>list.map(t=>`<span class="chip">${esc(tags[t].en)}</span>`).join('');
 const photo=c=>`<button class="atlas-photo" data-image="${c.id}" aria-label="Connections for ${esc(c.title)}"><img src="${c.image}" alt="${esc(c.title)}" loading="lazy"></button>`;
 const related=id=>{const peers=new Map();for(const s of registry.all().filter(s=>s.ids.includes(id)))for(const other of s.ids.filter(i=>i!==id)){const old=peers.get(other)||new Set();s.tags.forEach(t=>old.add(t));peers.set(other,old);}return [...peers].map(([id,t])=>({card:byId.get(id),tags:[...t]}));};
 function render(){const all=registry.all(),q=$('search').value.trim().toLowerCase(),tag=$('category-filter').value,match=c=>!q||[c.title,c.zh,...c.visual.flatMap(t=>[tags[t].en,tags[t].zh])].join(' ').toLowerCase().includes(q);for(const m of ['sets','images']){$('atlas-'+m).classList.toggle('active',mode===m);$('atlas-'+m).setAttribute('aria-pressed',mode===m);}$('atlas-focus').hidden=!focus;$('atlas-focus').textContent=focus?`${byId.get(focus).title} ×`:'';
 if(mode==='sets'){const shown=all.filter(s=>(!focus||s.ids.includes(focus))&&(tag==='all'||s.tags.includes(tag))&&s.ids.some(id=>match(byId.get(id))));$('library-count').textContent=`${shown.length} sets`;$('library-grid').className='atlas-sets';$('library-grid').innerHTML=shown.slice(0,limit).map(s=>`<article class="atlas-set"><div class="atlas-trio">${s.ids.map(id=>photo(byId.get(id))).join('')}</div><div class="atlas-caption"><div class="chips">${chips(s.tags)}</div><button class="text-button set-remove" data-remove="${s.key}" aria-label="Remove set: ${esc(s.ids.map(id=>byId.get(id).title).join(', '))}">Remove</button></div></article>`).join('')||'<p class="empty">No sets. Make one with ＋ New set.</p>';$('atlas-more').hidden=shown.length<=limit;
 }else{const shown=cards.filter(c=>(tag==='all'||(tag==='custom'?registry.all().some(s=>s.tags.includes('custom')&&s.ids.includes(c.id)):c.visual.includes(tag)))&&match(c));$('library-count').textContent=`${shown.length} images`;$('library-grid').className='atlas-images';$('library-grid').innerHTML=shown.map(c=>`<article>${photo(c)}<div class="atlas-caption"><span>${related(c.id).length} connections</span><button class="atlas-add" data-build="${c.id}" aria-label="Start a set with ${esc(c.title)}">＋</button></div></article>`).join('')||'<p class="empty">No images.</p>';$('atlas-more').hidden=true;}
 }
 function detail(id){const c=byId.get(id);if(!c)return;const peers=related(id),sets=registry.all().filter(s=>s.ids.includes(id));$('detail-content').innerHTML=`<div class="atlas-detail-top"><img src="${c.image}" alt="${esc(c.title)}"><div><h2>${esc(c.title)}</h2><div class="chips">${chips(c.visual)}</div><div class="atlas-detail-actions"><button class="quiet" data-find-sets="${id}">${sets.length} sets ↗</button><button class="quiet" data-build="${id}">＋ New set</button><a href="${c.source}" target="_blank" rel="noopener noreferrer">Are.na ↗</a></div></div></div><div class="section-title"><h2>${peers.length} connections</h2></div><div class="atlas-related">${peers.map(({card,tags:t})=>`<article>${photo(card)}<div class="chips">${chips(t)}</div></article>`).join('')}</div>`;if(!$('detail').open)$('detail').showModal();$('detail').scrollTop=0;}
 function changed(ids=[],text='Saved · ready in Match'){const saved=onChange(ids);$('library-status').textContent=saved?text:'Updated · browser storage unavailable';render();}
 function drawBuilder(){ $('builder-count').textContent=`${selection.length} / 3`;$('save-set').disabled=selection.length!==3;$('builder-slots').innerHTML=Array.from({length:3},(_,i)=>selection[i]?`<button data-unpick="${selection[i]}" aria-label="Remove ${esc(byId.get(selection[i]).title)}"><img src="${byId.get(selection[i]).image}" alt="${esc(byId.get(selection[i]).title)}"><span>×</span></button>`:`<div class="builder-empty">${i+1}</div>`).join('');$('builder-images').innerHTML=cards.map(c=>`<button draggable="true" data-pick="${c.id}" class="${selection.includes(c.id)?'picked':''}" aria-pressed="${selection.includes(c.id)}" aria-label="${esc(c.title)}"><img src="${c.image}" alt="${esc(c.title)}" draggable="false">${selection.includes(c.id)?'<span>✓</span>':''}</button>`).join('');}
 function pick(id,toggle=true){if(!byId.has(id))return;if(selection.includes(id)){if(toggle)selection=selection.filter(i=>i!==id);}else if(selection.length<3)selection.push(id);$('builder-status').textContent='Choose or drag three images.';drawBuilder();}
 function build(ids=[]){selection=ids;drawBuilder();$('builder-status').textContent='Choose or drag three images.';$('set-builder').showModal();}
 function click(e){const remove=e.target.closest('[data-remove]'),buildButton=e.target.closest('[data-build]'),image=e.target.closest('[data-image]'),sets=e.target.closest('[data-find-sets]');if(remove){lastRemoved=remove.dataset.remove;registry.remove(lastRemoved);$('set-undo').hidden=false;changed([],'Removed from Library & Match');}else if(buildButton){$('detail').close();build([+buildButton.dataset.build]);}else if(image)detail(+image.dataset.image);else if(sets){focus=+sets.dataset.findSets;mode='sets';limit=24;$('search').value='';$('category-filter').value='all';$('detail').close();location.hash='library';render();}}
 $('new-set').onclick=()=>build();$('builder-images').onclick=e=>{const b=e.target.closest('[data-pick]');if(b)pick(+b.dataset.pick);};$('builder-slots').onclick=e=>{const b=e.target.closest('[data-unpick]');if(b)pick(+b.dataset.unpick);};$('builder-images').ondragstart=e=>{const b=e.target.closest('[data-pick]');if(b)e.dataTransfer.setData('text/plain',b.dataset.pick);};$('builder-slots').ondragover=e=>e.preventDefault();$('builder-slots').ondrop=e=>{e.preventDefault();pick(+e.dataTransfer.getData('text/plain'),false);};
 $('save-set').onclick=()=>{if(!registry.add(selection)){$('builder-status').textContent='Already in Library.';return;}$('set-builder').close();mode='sets';focus=null;$('search').value='';$('category-filter').value='all';changed(selection);};$('set-undo').onclick=()=>{registry.undoRemove(lastRemoved);lastRemoved=null;$('set-undo').hidden=true;changed([],'Restored to Library & Match');};
 $('library-grid').onclick=click;$('detail-content').onclick=click;for(const m of ['sets','images'])$('atlas-'+m).onclick=()=>{mode=m;focus=null;limit=24;render();};for(const id of ['search','category-filter'])$(id).addEventListener(id==='search'?'input':'change',()=>{limit=24;render();});$('filters-clear').onclick=()=>{$('search').value='';$('category-filter').value='all';focus=null;limit=24;render();};$('atlas-focus').onclick=()=>{focus=null;render();};$('atlas-more').onclick=()=>{limit+=24;render();};
 for(const [id,t] of Object.entries(tags)){const option=document.createElement('option');option.value=id;option.textContent=t.en;$('category-filter').append(option);}
 return {show:render,detail};
}
